const entrada = items[0].json;
const clientes = entrada.body?.clientes ?? entrada.clientes ?? [];

if (!Array.isArray(clientes) || clientes.length === 0) {
  throw new Error('O payload precisa conter uma lista em "clientes".');
}

const recomendacoes = {
  Conservador: {
    tipo: 'Renda fixa',
    mensagem: 'Olá, {{nome}}! Para o seu perfil conservador, opções de renda fixa podem oferecer mais previsibilidade e segurança. Avalie alternativas compatíveis com seus objetivos e prazo.'
  },
  Moderado: {
    tipo: 'Carteira diversificada',
    mensagem: 'Olá, {{nome}}! Para o seu perfil moderado, uma carteira diversificada entre renda fixa e renda variável pode equilibrar segurança e potencial de crescimento. Avalie alternativas compatíveis com seus objetivos e prazo.'
  },
  Arrojado: {
    tipo: 'Renda variável',
    mensagem: 'Olá, {{nome}}! Para o seu perfil arrojado, uma parcela maior em renda variável pode buscar maior potencial de retorno, sempre considerando os riscos. Avalie alternativas compatíveis com seus objetivos e prazo.'
  }
};

return clientes.map((cliente) => {
  const perfil = cliente.perfil ?? 'Não informado';
  const modelo = recomendacoes[perfil] ?? {
    tipo: 'Análise necessária',
    mensagem: 'Olá, {{nome}}! Não foi possível identificar seu perfil de investidor. Faça uma nova análise antes de escolher um investimento.'
  };

  return {
    json: {
      nome: cliente.nome ?? '',
      email: cliente.email ?? '',
      saldo: cliente.saldo ?? '',
      perfil,
      recomendacao: modelo.tipo,
      mensagem: modelo.mensagem.replace('{{nome}}', cliente.nome ?? 'cliente')
    }
  };
});
